        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return r, c
        return None

    def backtrack(used_mask):
        empty_pos = find_empty()
        if empty_pos is None:
            return True

        r, c = empty_pos

        for i in range(N):
