def max_distance_between_primes(nums):
    """
    Calculates the maximum distance between the positions of two prime numbers in the sequence.
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    first_prime_idx = -1
    last_prime_idx = -1

    for i in range(len(nums)):
        if is_prime(nums[i]):
            if first_prime_idx == -1:
                first_prime_idx = i
            last_prime_idx = i

    return last_prime_idx - first_prime_idx
